/**
 * The poster (PRD §8.7; PRD v2 §3.1): generated from the same layout the
 * engine builds from, committed, and regenerated by the build, so it cannot
 * drift from the registry; since v2 it is the hero, the frame the engine opens
 * on, every company drawn as its own building. The test renders it again and
 * compares with the committed file byte for byte, and checks what it must and
 * must not contain.
 */
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { LAYOUT } from '@/world/placement/layout.generated';
import { P, heroFrame, posterSolids, renderPoster } from '../../scripts/world/render-poster.mjs';

const FILE = path.resolve(__dirname, '../../public/world/poster-far.svg');

describe('the poster', () => {
  const svg = renderPoster(LAYOUT);
  it('is the committed file, byte for byte', () => {
    expect(fs.readFileSync(FILE, 'utf8')).toBe(svg);
  });
  // PRD v2 §3.1: the poster is the hero frame, so it draws what lies near that frame, every company's lot a prism
  it('draws every lot near the hero frame as a prism (all of the estate’s), every region label, and the dashed raw-export road', () => {
    const f = heroFrame(LAYOUT), inFrame = (b: { x0: number; x1: number; y0: number; y1: number }) => { const [x, y] = P((b.x0 + b.x1) / 2, (b.y0 + b.y1) / 2, 0); return x >= f.x && x <= f.x + f.w && y >= f.y && y <= f.y + f.h; };
    const tops = (svg.match(/<path class="t" /g) ?? []).length;
    expect(tops).toBeGreaterThan(LAYOUT.blocks.filter((b) => b.region === 'estate').length * 2);
    expect(tops).toBeLessThanOrEqual(posterSolids(LAYOUT).length + 1);
    // every lot whose middle lies in the frame is drawn (its top is in the file's count), the estate's among them
    const lotsIn = LAYOUT.blocks.flatMap((b) => b.lots).filter((l) => inFrame(l.box));
    expect(lotsIn.length).toBeGreaterThan(100);
    expect(tops).toBeGreaterThanOrEqual(lotsIn.length + 1);
    for (const l of LAYOUT.labels.filter((x) => x.level === 'far')) expect(svg).toContain(l.text.toUpperCase());
    expect(svg).toContain('stroke-dasharray');
  });
  it('carries no figure, no company and no status: the world at rest', () => {
    expect(svg).not.toMatch(/Published|No model yet|INTP|SMGR|PTBA|ITMG/);
    expect(svg).toMatch(/aria-label="The industrial estate as the world opens/);
  });
  it('is small enough to be the first paint (gate 4, O8: 65 KB before the far view was written compactly)', () => {
    expect(svg.length).toBeLessThan(24 * 1024);
  });
  it('keeps the frame the stage was laid out for: the aspect of the 1600 by 952 image, centred on the hero', () => {
    const [x, y, w, h] = svg.match(/viewBox="([^"]+)"/)![1].split(' ').map(Number);
    expect(w / h).toBeCloseTo(1600 / 952, 2);
    const hb = LAYOUT.hero!, [cx, cy] = P((hb.x0 + hb.x1) / 2, (hb.y0 + hb.y1) / 2, 10);
    expect(Math.abs(x + w / 2 - cx)).toBeLessThan(1); expect(Math.abs(y + h / 2 - cy)).toBeLessThan(1);
  });
});
